pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract Orderbook is ReentrancyGuard{

    struct Order{
        uint256 id;
        address token;
        address seller;
        uint256 amount;
        uint256 pricePerToken;
        bool active;
    }

    IERC20 public usdc;
    uint256 public nextOrderId;
    mapping(uint256 => Order) public orders;

    event OrderCreated(
        uint256 indexed orderId,
        address indexed seller,
        address indexed token,
        uint256 amount,
        uint256 pricePerToken);

    event OrderFilled(
        uint256 indexed orderId,
        address indexed buyer,
        uint256 amount,
        uint256 totalCost
    );

    event OrderCancelled(uint256 indexed orderId, address indexed seller);

        constructor(IERC20 _usdc) {
        usdc = _usdc;
    }

    function createOrder(address token, uint256 amount, uint256 pricePerToken) external nonReentrant{
        require(amount > 0,"Invalid Amount");
        require(pricePerToken > 0,"Invalid Price");
        IERC20(token).transferFrom(msg.sender, address(this), amount);

        orders[nextOrderId] = Order({
            id: nextOrderId,
            token: token,
            seller: msg.sender,
            amount: amount,
            pricePerToken: pricePerToken,
            active: true
        });

        emit OrderCreated(nextOrderId,msg.sender,token,amount,pricePerToken);
        nextOrderId++;
    }

    function fillOrder(uint256 orderId, uint256 buyAmount) external nonReentrant{
        Order storage order = orders[orderId];
        require(order.active,"orderInactive");
        require(buyAmount > 0 && buyAmount <= order.amount,"InvalidAmount");

        uint256 totalCost = (buyAmount * order.pricePerToken) / 1e2;
        require(usdc.transferFrom(msg.sender, order.seller, totalCost),"USDC transfer fail");

        IERC20(order.token).transfer(msg.sender, buyAmount);
        order.amount -= buyAmount;

        if(order.amount == 0) {
            order.active = false;
         }
        emit OrderFilled(orderId, msg.sender, buyAmount, totalCost);
    }

    function cancelOrder(uint256 orderId) external nonReentrant{
        Order storage order = orders[orderId];
        require(order.active,"orderInactive");
        require(order.seller == msg.sender,"Not yourOrder");
        order.active = false;
        IERC20(order.token).transfer(msg.sender, order.amount);

        emit OrderCancelled(orderId, msg.sender);
    }
}

