// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract PropertyShareToken is ERC20, ERC20Votes, Ownable, ERC20Permit {
    mapping(address => bool) public isWhitelisted;
    mapping(address => bool) public isBlacklisted;
    address public marketplace;
    address public orderBook;
    uint256 public tokenId;

    // Snapshot functionality
    mapping(address => mapping(uint256 => uint256)) private _snapshots;
    mapping(uint256 => uint256) private _snapshotTimestamps;
    uint256 private _currentSnapshotId;

    event Snapshot(uint256 id);

    constructor(
        string memory name,
        string memory symbol,
        uint256 _tokenId,
        address initialOwner
    )
        ERC20(name, symbol)
        ERC20Permit(name)
        Ownable(initialOwner)
    {
        tokenId = _tokenId;
    }

    function setMarketplace(address _marketplace) external onlyOwner {
        require(_marketplace != address(0), "Invalid address");
        marketplace = _marketplace;
    }

        function setOrderBook(address _orderBook) external onlyOwner {
        require(_orderBook != address(0), "Invalid address");
        orderBook = _orderBook;
      }

    function getTokenId() external view returns (uint256) {
        return tokenId;
    }

    function addToWhitelist(address user) external onlyOwner {
        isWhitelisted[user] = true;
    }

    function removeFromWhitelist(address user) external onlyOwner {
        isWhitelisted[user] = false;
    }

    function blockAddress(address user) external onlyOwner {
        isBlacklisted[user] = true;
    }

    function unblockAddress(address user) external onlyOwner {
        isBlacklisted[user] = false;
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) public onlyOwner {
        _burn(from, amount);
    }

    function snapshot() public onlyOwner returns (uint256) {
        _currentSnapshotId++;
        _snapshotTimestamps[_currentSnapshotId] = block.timestamp;
        emit Snapshot(_currentSnapshotId);
        return _currentSnapshotId;
    }

    function balanceOfAt(address account, uint256 snapshotId) public view returns (uint256) {
        require(snapshotId > 0 && snapshotId <= _currentSnapshotId, "Invalid snapshot ID");
        return _snapshots[account][snapshotId] > 0 ? _snapshots[account][snapshotId] : balanceOf(account);
    }


    function _update(address from, address to, uint256 value)
        internal
        override(ERC20, ERC20Votes)
    {
        if (from == address(0) || to == address(0)) {
            super._update(from, to, value);
         if (_currentSnapshotId > 0) {
                if (from != address(0)) _snapshots[from][_currentSnapshotId] = balanceOf(from);
                if (to != address(0)) _snapshots[to][_currentSnapshotId] = balanceOf(to);
            }
            return;
        }

        //   require(isWhitelisted[from], "Sender not whitelisted");
        //   require(isWhitelisted[to], "Recipient not whitelisted");
        require(msg.sender == marketplace || msg.sender == orderBook || msg.sender == owner(),  "Tokens are non-transferrable");

          super._update(from, to, value);

        if (_currentSnapshotId > 0) {
            _snapshots[from][_currentSnapshotId] = balanceOf(from);
            _snapshots[to][_currentSnapshotId] = balanceOf(to);
        }

    }

    function nonces(address owner)
        public
        view
        override(ERC20Permit, Nonces)
        returns (uint256)
    {
        return super.nonces(owner);
    }
}

